/* Fetch's art: a golden retriever puppy sitting, sniffing, running, and back with a newspaper or a stick. Each clip is a strip of square frames cut from a generated animation, keyed to
 * transparent WebP; every clip shares one crop, so frames line up across clips. As data URIs so
 * one install brings everything. */

export const FETCH_ART = {
  sit: "data:image/webp;base64,",
  sniff:
    "data:image/webp;base64,",
  run: "data:image/webp;base64,",
  paper:
    "data:image/webp;base64,",
  stick:
    "data:image/webp;base64,",
};

export const FETCH_FRAMES = {
  /** One frame, in image px. */
  w: 150,
  h: 150,
  clips: {
    sit: { frames: 10, fps: 8 },
    sniff: { frames: 5, fps: 10 },
    run: { frames: 7, fps: 15 },
    paper: { frames: 10, fps: 8 },
    stick: { frames: 10, fps: 8 },
  },
} as const;
